require_once '../inc/auth.php'; require_once '../../config/koneksi.php'; $title='Edit Produk'; $id=(int)($_GET['id']??0); $s=$conn->prepare("SELECT * FROM produk WHERE id=?");$s->bind_param('i',$id);$s->execute();$data=$s->get_result()->fetch_assoc();if(!$data)die('Produk tidak ditemukan.');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nama=trim($_POST['nama_produk']??'');$des=trim($_POST['deskripsi']??'');$stok=max(0,(int)($_POST['stok']??$data['stok']));$foto=$data['foto'];
 if($nama==='')$error='Nama produk wajib diisi.';
 if(!$error && !empty($_FILES['foto']['name'])){require_once '../../inc/upload.php';$up=upload_image($_FILES['foto'],'../../uploads/produk/');if(!$up['ok'])$error=$up['error'];else{$foto=$up['name'];if($data['foto']&&file_exists('../../uploads/produk/'.$data['foto']))@unlink('../../uploads/produk/'.$data['foto']);}}
 if(!$error){$s=$conn->prepare("UPDATE produk SET nama_produk=?,deskripsi=?,foto=?,stok=? WHERE id=?");$s->bind_param('sssii',$nama,$des,$foto,$stok,$id);$s->execute();header('Location:index.php');exit;}
}
include '../inc/header.php'; ?><div class="page-title"><h1>Edit Produk</h1></div><div class="form-card"><?php if($error): ?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif; ?><form method="post" enctype="multipart/form-data"><div class="form-group"><label>Nama Produk</label><input name="nama_produk" value="<?=htmlspecialchars($_POST['nama_produk']??$data['nama_produk'])?>" required></div><div class="form-group"><label>Stok</label><input type="number" name="stok" min="0" value="<?=htmlspecialchars($_POST['stok']??$data['stok'])?>" required></div><div class="form-group"><label>Deskripsi</label><textarea name="deskripsi" required><?=htmlspecialchars($_POST['deskripsi']??$data['deskripsi'])?></textarea></div><div class="form-group"><label>Ganti Foto</label><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"><?php if($data['foto']): ?><br><img class="preview" src="../../uploads/produk/<?=htmlspecialchars($data['foto'])?>"><?php endif; ?></div><button class="btn green">Update</button> <a class="btn gray" href="index.php">Batal</a></form></div><?php include '../inc/footer.php'; ?>